-- Hand-written: offer links, send rows and acceptance certificates (M4.5), generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `offer_links_purpose_insert` BEFORE INSERT ON `offer_links` WHEN NEW.purpose NOT IN ('offer', 'confirmation') BEGIN SELECT RAISE(ABORT, 'offer_links_purpose: an offer link is for an offer or a confirmation'); END;
--> statement-breakpoint
CREATE TRIGGER `offer_links_purpose_update` BEFORE UPDATE OF purpose ON `offer_links` WHEN NEW.purpose NOT IN ('offer', 'confirmation') BEGIN SELECT RAISE(ABORT, 'offer_links_purpose: an offer link is for an offer or a confirmation'); END;
--> statement-breakpoint
CREATE TRIGGER `offer_links_fixed` BEFORE UPDATE ON `offer_links` WHEN NEW.`token_hash` IS NOT OLD.`token_hash` OR NEW.`send_id` IS NOT OLD.`send_id` OR NEW.`acceptance_id` IS NOT OLD.`acceptance_id` OR NEW.`document_id` IS NOT OLD.`document_id` OR NEW.`version_group_id` IS NOT OLD.`version_group_id` OR NEW.`client_id` IS NOT OLD.`client_id` OR NEW.`contact_id` IS NOT OLD.`contact_id` OR NEW.`email` IS NOT OLD.`email` OR NEW.`purpose` IS NOT OLD.`purpose` OR NEW.`expires_at` IS NOT OLD.`expires_at` OR NEW.`created_at` IS NOT OLD.`created_at` OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS NOT OLD.revoked_at) BEGIN SELECT RAISE(ABORT, 'offer_links_fixed: an offer link only gets revoked, once'); END;
--> statement-breakpoint
CREATE TRIGGER `acceptance_certificates_no_update` BEFORE UPDATE ON `acceptance_certificates` BEGIN SELECT RAISE(ABORT, 'acceptance_certificates is append-only'); END;
--> statement-breakpoint
CREATE TRIGGER `acceptance_certificates_no_delete` BEFORE DELETE ON `acceptance_certificates` BEGIN SELECT RAISE(ABORT, 'acceptance_certificates is append-only'); END;
