CREATE TRIGGER `document_sends_fixed` BEFORE UPDATE ON `document_sends` WHEN NEW.`id` IS NOT OLD.`id` OR NEW.`document_id` IS NOT OLD.`document_id` OR NEW.`version_group_id` IS NOT OLD.`version_group_id` OR NEW.`client_id` IS NOT OLD.`client_id` OR NEW.`attach_pdf` IS NOT OLD.`attach_pdf` OR NEW.`kind` IS NOT OLD.`kind` OR NEW.`created_by` IS NOT OLD.`created_by` OR NEW.`created_at` IS NOT OLD.`created_at` OR (OLD.queued_at IS NOT NULL AND NEW.queued_at IS NOT OLD.queued_at) OR (OLD.cancelled_at IS NOT NULL AND NEW.cancelled_at IS NOT OLD.cancelled_at) OR (NEW.contact_id IS NOT OLD.contact_id AND NEW.contact_id IS NOT NULL) OR (NEW.email IS NOT OLD.email AND NEW.email IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'document_sends_fixed: a send changes only when it is queued or cancelled, or when its contact is erased'); END;
